1021→// ─────────────────────── Re-query call trees ───────────────────────
1022→
1023→/**
1024→ * 判断 narrative 是否来自 perfetto 源。
1025→ * perfetto runId 形如 "bk26b-perfetto-triad/2026-07-15_10-36-27"（含 perfetto）。
1026→ */
1027→function isPerfettoSource(narrative: NarrativeReport): boolean {
1028→  return /perfetto/i.test(narrative.runId);
1029→}
1030→
1031→/**
1032→ * perfetto callTree 节点（来自 perfetto-profile-summary.json）的松散结构。
1033→ * 字段：name/totalMs/totalPct/count/layer/children。
1034→ */
1035→interface PerfettoNode {
1036→  name: string;
1037→  totalMs?: number;
1038→  totalPct?: number;
1039→  count?: number;
1040→  layer?: string;
1041→  children?: PerfettoNode[];
1042→}
1043→
1044→/**
1045→ * 在 perfetto callTree 里按节点名搜索子树。
1046→ * 先精确匹配 rootMarker；失败则按名字核心部分（去前缀/去 Gfx./URP. 等命名空间差异）子串回退。
1047→ *
1048→ * 名字归一化（呈现层职责，非判定）：narrative LLM 可能用 atrace slice 名
1049→ * （如 Gfx.WaitForPresentOnGfxThread）而 callTree 用 Unity marker 名（如 URP.WaitForPresent），
1050→ * 两者指同一等待点。render 层做名字归一化让树能渲染，不做任何性能判定。
1051→ */
1052→function findPerfettoSubtree(root: PerfettoNode, targetName: string): PerfettoNode | null {
1053→  // 1. 精确匹配
1054→  const exact = findPerfettoSubtreeExact(root, targetName);
1055→  if (exact) return exact;
1056→
1057→  // 2. 子串回退：取 targetName 的核心部分（去前缀，取最后一个 CamelCase 词组）
1058→  //    如 Gfx.WaitForPresentOnGfxThread → WaitForPresent；Core.Update → Update
1059→  //    在树里找 name 包含核心词的节点，唯一匹配则用，多匹配则不用（避免误匹配）
1060→  const core = extractNameCore(targetName);
1061→  if (!core || core.length < 4) return null;  // 太短的核心词易误匹配，不回退
1062→  const candidates: PerfettoNode[] = [];
1063→  collectContainsMatch(root, core, candidates);
1064→  if (candidates.length === 1) return candidates[0];
1065→  return null;
1066→}
1067→
1068→function findPerfettoSubtreeExact(node: PerfettoNode, targetName: string): PerfettoNode | null {
1069→  if (node.name === targetName) return node;
1070→  for (const child of node.children ?? []) {
1071→    const found = findPerfettoSubtreeExact(child, targetName);
1072→    if (found) return found;
1073→  }
1074→  return null;
1075→}
1076→
1077→/**
1078→ * 提取 marker 名的核心部分用于模糊回退匹配。
1079→ * Gfx.WaitForPresentOnGfxThread → WaitForPresent（去 Gfx. 前缀，去 OnGfxThread 后缀）
1080→ * URP.WaitForPresent → WaitForPresent
1081→ * Core.Update → Update
1082→ */
1083→function extractNameCore(name: string): string {
1084→  // 去前缀（Gfx./URP./Core./Inl_ 等）
1085→  let core = name.replace(/^(Gfx|URP|Core|Inl|PlayerLoop|PostLateUpdate|FinishFrameRendering)\./, '');
1086→  // 去常见后缀（OnGfxThread/OnMainThread 等）
1087→  core = core.replace(/On(GfxThread|MainThread|RenderThread)$/i, '');
1088→  // 取第一个 CamelCase 词组（WaitForPresentOnGfxThread → WaitForPresent）
1089→  const m = core.match(/^([A-Z][a-z]+(?:[A-Z][a-z]+)*)/);
1090→  return m ? m[1] : core;
1091→}
1092→
1093→function collectContainsMatch(node: PerfettoNode, core: string, out: PerfettoNode[]): void {
1094→  if (node.name.includes(core)) out.push(node);
1095→  for (const child of node.children ?? []) collectContainsMatch(child, core, out);
1096→}
1097→
1098→/**
1099→ * 把 perfetto 节点转成 DrillDownNode 兼容结构（renderTreeHTML 只读这些字段）。
1100→ * per-frame avg = totalMs / count（count = 出现帧数）。
1101→ * selfMsPerFrame：perfetto 没直接给 self，置 0（renderTreeHTML 仅在 self>0 且 <total 时显示）。
1102→ * pctOfRoot：用 totalPct/100（相对 UnityMain 总窗口）。
1103→ */
1104→function perfettoNodeToDrillDown(
1105→  node: PerfettoNode,
1106→  thread: string,
1107→  rootPctOfRoot: number,
1108→): DrillDownNode {
1109→  const totalMs = node.totalMs ?? 0;
1110→  const count = node.count ?? 1;
1111→  const totalMsPerFrame = count > 0 ? totalMs / count : 0;
1112→  const pctOfRoot = node.totalPct != null ? node.totalPct / 100 : 0;
1113→  return {
1114→    name: node.name,
1115→    thread,
1116→    totalMsPerFrame,
1117→    selfMsPerFrame: 0,  // perfetto summary 无 self 字段，置 0（renderTreeHTML 不显示 self 行）
1118→    pctOfRoot,
1119→    presentFrames: count,
1120→    children: (node.children ?? []).map(c => perfettoNodeToDrillDown(c, thread, rootPctOfRoot)),
1121→  };
1122→}
1123→
1124→/**
1125→ * perfetto 源的 callTree 重查：读 perfetto-profile-summary.json 的 callTrees，
1126→ * 按 rootMarker 名在树里搜索子树，转成 DrillDownNode。
1127→ * 不走 sqlite / drillDownMarker（那是 unity 工具）。
1128→ *
1129→ * @param dir  run 输出目录（含 narrative.json），形如 .../bk26b-perfetto-triad/2026-07-15_10-36-27
1130→ *             perfetto triad 数据在 dir 的父目录下的 cur/perfetto-profile-summary.json
1131→ */
1132→function requeryPerfettoTrees(
1133→  narrative: NarrativeReport,
1134→  refs: { key: string; rootMarker: string }[],
1135→  dir: string,
1136→): Map<string, DrillDownNode | null> {
1137→  const map = new Map<string, DrillDownNode | null>();
1138→  if (refs.length === 0) return map;
1139→
1140→  // perfetto triad 数据目录：dir 是 .../<runBase>/<timestamp>，triad root = <runBase>
1141→  // perfetto-profile-summary.json 在 <runBase>/cur/ 下（多态报告用 cur 态作主树）
1142→  const triadRoot = path.dirname(dir);  // 去掉时间戳子目录
1143→  const summaryPath = path.join(triadRoot, 'cur', 'perfetto-profile-summary.json');
1144→
1145→  if (!fs.existsSync(summaryPath)) {
1146→    console.warn(`[render-html] perfetto summary not found: ${summaryPath} — all callTrees fallback`);
1147→    for (const ref of refs) map.set(ref.key, null);
1148→    return map;
1149→  }
1150→
1151→  let summary: { callTrees?: { thread?: string; root?: PerfettoNode }[] };
1152→  try {
1153→    summary = JSON.parse(fs.readFileSync(summaryPath, 'utf-8'));
1154→  } catch (e) {
1155→    console.warn(`[render-html] perfetto summary parse failed: ${(e as Error).message} — all callTrees fallback`);
1156→    for (const ref of refs) map.set(ref.key, null);
1157→    return map;
1158→  }
1159→
1160→  const callTrees = Array.isArray(summary.callTrees) ? summary.callTrees : [];
1161→  if (callTrees.length === 0) {
1162→    console.warn('[render-html] perfetto callTrees empty in summary — all callTrees fallback');
1163→    for (const ref of refs) map.set(ref.key, null);
1164→    return map;
1165→  }
1166→
1167→  // 用第一棵树（UnityMain）作主搜索树
1168→  const mainTree = callTrees[0];
1169→  const thread = mainTree.thread ?? 'UnityMain';
1170→  const root = mainTree.root;
1171→  if (!root) {
1172→    console.warn('[render-html] perfetto main tree root missing — all callTrees fallback');
1173→    for (const ref of refs) map.set(ref.key, null);
1174→    return map;
1175→  }
1176→
1177→  for (const ref of refs) {
1178→    const subtree = findPerfettoSubtree(root, ref.rootMarker);
1179→    if (subtree) {
1180→      const tree = perfettoNodeToDrillDown(subtree, thread, 1);
1181→      map.set(ref.key, tree);
1182→      console.log(`[render-html] perfetto tree OK: "${ref.rootMarker}" → ${tree.totalMsPerFrame.toFixed(2)}ms/frame`);
1183→    } else {
1184→      console.warn(`[render-html] perfetto tree NOT FOUND: "${ref.rootMarker}" — fallback to note`);
1185→      map.set(ref.key, null);
1186→    }
1187→  }
1188→  return map;
1189→}
1190→
1191→async function requeryTrees(
1192→  narrative: NarrativeReport,
1193→  dbPath: string | undefined,
1194→  dir: string,
1195→): Promise<Map<string, DrillDownNode | null>> {
1196→  const map = new Map<string, DrillDownNode | null>();
1197→
1198→  // Collect items with callTree.rootMarker
1199→  type ItemRef = { key: string; rootMarker: string };
1200→  const refs: ItemRef[] = [];
1201→  for (const sec of narrative.sections) {
1202→    sec.items.forEach((item, i) => {
1203→      if (item.callTree?.rootMarker) {
1204→        refs.push({ key: `${sec.heading}::${i}`, rootMarker: item.callTree.rootMarker });
1205→      }
1206→    });
1207→  }
1208→
1209→  if (refs.length === 0) return map;
1210→
1211→  // perfetto 源：走 perfetto-profile.json，不走 sqlite（DR-45 断链 4 修复）
1212→  if (isPerfettoSource(narrative)) {
1213→    return requeryPerfettoTrees(narrative, refs, dir);
1214→  }
1215→
1216→  // unity 源：走 sqlite + drillDownMarker
1217→  let db: ReturnType<typeof openPrismDb> | null = null;
1218→  try {
1219→    db = openPrismDb(dbPath);
1220→  } catch (e) {
1221→    console.error('[render-html] Cannot open DB — all callTrees will show note text:', (e as Error).message);
1222→    return map;
1223→  }
1224→
1225→  for (const ref of refs) {
1226→    try {
1227→      const result = drillDownMarker(db, {
1228→        runId: narrative.runId,
1229→        rootMarker: ref.rootMarker,
1230→        maxDepth: 6,
1231→        minMsPerFrame: 0.05,
1232→        topPerLevel: 8,
1233→      });
1234→      const tree = result.data.tree;
1235→      map.set(ref.key, tree);
1236→      console.log(`[render-html] tree OK: "${ref.rootMarker}" → ${result.data.rootTotalMsPerFrame.toFixed(2)}ms/frame`);
1237→    } catch (e) {
1238→      console.warn(`[render-html] tree FAIL: "${ref.rootMarker}" — ${(e as Error).message}`);
1239→      map.set(ref.key, null);
1240→    }
1241→  }
1242→
1243→  try { db.close(); } catch { /* ignore */ }
1244→  return map;
1245→}
