1254→async function main(): Promise<void> {
1255→  const dir = getFlag('--dir') ?? 'data/prism-out/unity-outside-stressmove';
1256→
1257→  // Require narrative.json — do NOT fall back to findings.json
1258→  const narrativePath = path.join(dir, 'narrative.json');
1259→  if (!fs.existsSync(narrativePath)) {
1260→    console.error(`[render-html] ERROR: narrative.json not found at ${narrativePath}`);
1261→    console.error('[render-html] This renderer requires narrative.json (NarrativeReport shape). Run the narrative stage first.');
1262→    process.exit(1);
1263→  }
1264→
1265→  let narrative: NarrativeReport;
1266→  try {
1267→    narrative = JSON.parse(fs.readFileSync(narrativePath, 'utf-8')) as NarrativeReport;
1268→  } catch (e) {
1269→    console.error(`[render-html] ERROR: failed to parse narrative.json — ${(e as Error).message}`);
1270→    process.exit(1);
1271→  }
1272→
1273→  // DR-44 A2: provenance 强制校验——非 LLM 产出的 narrative.json 拒绝渲染。
1274→  // 脚本拼的 narrative.json（无 narrativeProvenance 或 generatedBy !== 'LLM'）会被拦截，
1275→  // 强制走 narrative LLM 阶段。
1276→  if (
1277→    !narrative.narrativeProvenance ||
1278→    narrative.narrativeProvenance.generatedBy !== 'LLM'
1279→  ) {
1280→    const actual = narrative.narrativeProvenance?.generatedBy ?? 'missing';
1281→    console.error(
1282→      `[render-html] ERROR: narrative.json 的 narrativeProvenance.generatedBy 不是 'LLM'（实际：${actual}）。` +
1283→        `脚本拼的 narrative.json 会被拒绝渲染——必须走 narrative LLM 阶段（DR-44 A2）。`,
1284→    );
1285→    process.exit(1);
1286→  }
1287→
1288→  // Optional verdict.json for numeric metrics
1289→  let verdict: Verdict | null = null;
1290→  const verdictPath = path.join(dir, 'verdict.json');
1291→  if (fs.existsSync(verdictPath)) {
1292→    try {
1293→      verdict = JSON.parse(fs.readFileSync(verdictPath, 'utf-8')) as Verdict;
1294→    } catch {
1295→      console.warn('[render-html] verdict.json found but failed to parse — metric strip will show "—"');
1296→    }
1297→  }
1298→
1299→  const dbPath = getFlag('--db');
1300→  console.log(`[render-html] dir=${dir}  runId=${narrative.runId}  rating=${narrative.rating}`);
1301→  console.log(`[render-html] sections=${narrative.sections.length}  topConclusions=${narrative.topConclusions.length}`);
1302→
1303→  const treesByItemKey = await requeryTrees(narrative, dbPath, dir);
1304→
1305→  const html = renderHTML({ narrative, verdict, treesByItemKey });
1306→
1307→  const outPath = path.join(dir, 'report.html');
1308→  fs.writeFileSync(outPath, html, 'utf-8');
1309→
1310→  const fileSizeKB = (fs.statSync(outPath).size / 1024).toFixed(1);
1311→  console.log(`\n[render-html] Written: ${outPath}`);
1312→  console.log(`[render-html] Size: ${fileSizeKB} KB`);
1313→  console.log(`[render-html] Call-trees re-queried: ${treesByItemKey.size}`);
1314→}
1315→
1316→main().catch(e => {
1317→  console.error('[render-html] Fatal:', e);
1318→  process.exit(1);
1319→});
