174→}
175→
176→// ─────────────────────── 2. narrative.json 结构契约 ───────────────────────
177→// DR-45 §3.2：narrative LLM 产出后，校验 sections 结构是否符合模板章节骨架。
178→// 需 --dir 指向 run 输出目录。
179→
180→if (dirArg) {
181→  // 相对路径相对于 cwd（通常 web/），绝对路径直接用
182→  const runDir = path.isAbsolute(dirArg) ? dirArg : path.resolve(process.cwd(), dirArg);
183→  const narrativePath = path.join(runDir, 'narrative.json');
184→  const reportHtmlPath = path.join(runDir, 'report.html');
185→
186→  console.log('\n[2] narrative.json 结构契约（需 --dir）');
187→
188→  if (!fs.existsSync(narrativePath)) {
189→    assert(false, 'narrative.json 存在', { path: narrativePath });
190→  } else {
191→    let narrative: NarrativeReport;
192→    try {
193→      narrative = JSON.parse(fs.readFileSync(narrativePath, 'utf-8')) as NarrativeReport;
194→    } catch (e) {
195→      assert(false, 'narrative.json 可解析为 JSON', (e as Error).message);
196→      narrative = undefined as unknown as NarrativeReport;
197→    }
198→
199→    if (narrative) {
200→      // 2a. provenance 校验（DR-44 A2，同 render-html）
201→      assert(
202→        narrative.narrativeProvenance?.generatedBy === 'LLM',
203→        "narrativeProvenance.generatedBy === 'LLM'",
204→        { actual: narrative.narrativeProvenance?.generatedBy ?? 'missing' },
205→      );
206→
207→      // 2b. 必填字段
208→      assert(typeof narrative.overview === 'string' && narrative.overview.length > 20, 'overview 非空 (>20 chars)');
209→      assert(['excellent', 'pass', 'weak', 'fail'].includes(narrative.rating), 'rating 合法', narrative.rating);
210→      assert(Array.isArray(narrative.topConclusions) && narrative.topConclusions.length >= 3, 'topConclusions >= 3 条', { count: narrative.topConclusions?.length });
211→      assert(Array.isArray(narrative.sections) && narrative.sections.length >= 3, 'sections >= 3 个', { count: narrative.sections?.length });
212→      assert(Array.isArray(narrative.prioritySummary) && narrative.prioritySummary.length >= 1, 'prioritySummary 非空');
213→
214→      // 2c. judgmentBoundary 诚实声明（超越作文机的关键）
215→      assert(
216→        narrative.judgmentBoundary && Array.isArray(narrative.judgmentBoundary.canJudge) && narrative.judgmentBoundary.canJudge.length > 0,
217→        'judgmentBoundary.canJudge 非空（诚实声明能判什么）',
218→      );
219→      assert(
220→        narrative.judgmentBoundary && Array.isArray(narrative.judgmentBoundary.cannotJudge) && narrative.judgmentBoundary.cannotJudge.length > 0,
221→        'judgmentBoundary.cannotJudge 非空（诚实声明判不了什么）',
222→      );
223→
224→      // 2d. topConclusions 三维标注 + judgability（narrative-prompt 要求每条必标）
225→      const conclusionsMissingDims = narrative.topConclusions.filter(c => !c.dimensions || c.dimensions.length === 0);
226→      assert(conclusionsMissingDims.length === 0, '每条 topConclusion 有 dimensions 三维标注', { missing: conclusionsMissingDims.length });
227→      const conclusionsMissingJudg = narrative.topConclusions.filter(c => !c.judgability);
228→      assert(conclusionsMissingJudg.length === 0, '每条 topConclusion 有 judgability', { missing: conclusionsMissingJudg.length });
229→
230→      // 2e. 审计字段不进 narrative（DR-41 规则 1）
231→      const narrativeStr = JSON.stringify(narrative);
232→      assert(!narrativeStr.includes('evidenceIds'), 'narrative.json 无 evidenceIds 审计字段');
233→      assert(!narrativeStr.includes('findingIds') || narrative.sections.some(s => s.items.some(i => i.findingIds)), 'findingIds 只在 item 级别（关联 finding，非审计）');
234→      // 注：item.findingIds 是合法的（关联 finding 用），顶层 evidenceIds 才是禁止的
235→
236→      // 2f. sections 结构契约：每个 section 有 heading + items
237→      const badSections = narrative.sections.filter(s => !s.heading || !Array.isArray(s.items) || s.items.length === 0);
238→      assert(badSections.length === 0, '每个 section 有 heading + 非空 items', { badCount: badSections.length });
239→
240→      // 2g. callTree.rootMarker 覆盖率（防全 fallback 成 note）
241→      const itemsWithCallTree = narrative.sections.flatMap(s => s.items).filter(i => i.callTree?.rootMarker);
242→      const totalItems = narrative.sections.flatMap(s => s.items).length;
243→      const callTreeCoverage = totalItems > 0 ? itemsWithCallTree.length / totalItems : 0;
244→      if (callTreeCoverage < 0.3) {
245→        warn(`callTree.rootMarker 覆盖率偏低 (${(callTreeCoverage * 100).toFixed(0)}%)`, {
246→          hint: '大部分 item 没给 callTree.rootMarker，渲染时会全 fallback 成 note——可能 LLM 没按模板要求下钻',
247→        });
248→      } else {
249→        assert(true, `callTree.rootMarker 覆盖率 ${(callTreeCoverage * 100).toFixed(0)}% (>=30%)`);
250→      }
251→
252→      // 2h. 章节骨架对照模板（软约束 warning，不 fail）
253→      //     perfetto-multi-state 模板要求 §0-§7 八章，narrative 的 sections 是自由分群，
254→      //     不强制 1:1 匹配，但数量太少 = 可能没按模板组织。
255→      if (source === 'perfetto' && narrative.sections.length < 5) {
256→        warn('perfetto 报告 sections < 5，模板要求 §0-§7 八章', {
257→          actual: narrative.sections.length,
258→          hint: '可能 narrative LLM 拿到的是裸 prompt（{{REPORT_TEMPLATE}} 没注入），按自由分群交差了',
259→        });
260→      }
261→
262→      // 2i. 无万能套话（DR-41 规则 5 + dev-conventions §六）
263→      const boilerplate = ['建议单次任务削峰', '建议增量化', '建议分帧处理'];
264→      const foundBoilerplate = boilerplate.filter(phrase => narrativeStr.includes(phrase));
265→      assert(foundBoilerplate.length === 0, '无万能套话（"建议单次任务削峰"等）', { found: foundBoilerplate });
266→
267→      // 2j. prioritySummary 有 P0
268→      const hasP0 = narrative.prioritySummary.some(p => p.priority === 'P0');
269→      assert(hasP0, 'prioritySummary 有 P0 项');
270→
271→      // ── 3. report.html 视觉资产检查 ──
272→      console.log('\n[3] report.html 视觉资产（DR-41 五条硬规则 + 模板要求）');
273→
274→      if (!fs.existsSync(reportHtmlPath)) {
275→        assert(false, 'report.html 存在', { path: reportHtmlPath });
276→      } else {
277→        const html = fs.readFileSync(reportHtmlPath, 'utf-8');
278→
279→        // 3a. 调用树渲染（不是全 fallback）
280→        const fallbackCount = (html.match(/tree-section fallback/g) || []).length;
281→        // 真实树 = 含 tree-section class 但不含 fallback 的 div
282→        const allTreeSections = (html.match(/class="tree-section[^"]*"/g) || []).length;
283→        const realTreeCount = allTreeSections - fallbackCount;
284→        assert(realTreeCount > 0, `report.html 有真实调用树渲染 (>=1 棵，非全 fallback)`, { realTrees: realTreeCount, fallbacks: fallbackCount });
285→
286→        // 3b. 核心结论表
287→        assert(html.includes('top-conclusions'), 'report.html 含核心结论表');
288→        assert(html.includes('tc-rank'), '核心结论表有 rank 列');
289→
290→        // 3c. 已排除项（ruledOut，超越作文机的辨伪能力）
291→        assert(html.includes('ruled-out'), 'report.html 含已排除项（ruledOut）');
292→
293→        // 3d. 优化优先级表
294→        assert(html.includes('priority-table'), 'report.html 含优化优先级表');
295→
296→        // 3e. 严重度标注
297→        assert(html.includes('sev-dot') || html.includes('sev-chip'), 'report.html 含严重度标注');
298→
299→        // 3f. provenance 校验痕迹（render-html 的 DR-44 A2 校验通过了才会产出 html）
300→        assert(html.includes('Prism render-html') || html.includes('render-html'), 'report.html 由 render-html 产出');
301→
302→        // 3g. 无审计字段泄漏到 HTML
303→        assert(!html.includes('evidenceIds'), 'report.html 无 evidenceIds 泄漏');
304→        assert(!html.includes('selfCritique'), 'report.html 无 selfCritique 泄漏');
305→
306→        // 3h. 文件大小（太小说明内容单薄）
307→        const sizeKB = fs.statSync(reportHtmlPath).size / 1024;
308→        if (sizeKB < 20) {
309→          warn(`report.html 偏小 (${sizeKB.toFixed(1)} KB)`, {
310→            hint: 'v5.3 标杆报告内容充实，<20KB 可能内容单薄或缺视觉资产',
311→          });
312→        } else {
313→          assert(true, `report.html 大小合理 (${sizeKB.toFixed(1)} KB)`);
314→        }
315→      }
316→    }
317→  }
318→} else {
319→  console.log('\n[2] narrative.json 结构契约 — SKIP（未传 --dir）');
320→  console.log('[3] report.html 视觉资产 — SKIP（未传 --dir）');
321→  console.log('    提示：加 --dir data/prism-out/<run> 跑完整检查');
322→}
323→
324→// ─────────────────────── Summary ───────────────────────
325→
326→console.log(`\n${'─'.repeat(50)}`);
327→console.log(`Results: ${passCount} PASS, ${failCount} FAIL, ${warnings.length} WARN`);
328→if (warnings.length > 0) {
329→  console.log('\n⚠️  Warnings（验收时必须检查，不阻塞但可能暴露问题）:');
330→  warnings.forEach(w => console.log(w));
331→}
332→if (failCount > 0) {
333→  console.log('\nOVERALL: FAIL');
334→  process.exit(1);
335→} else {
336→  console.log('\nOVERALL: PASS' + (warnings.length > 0 ? ' (有 warning，验收时检查)' : ''));
337→  process.exit(0);
338→}
